#include <string>
#include <algorithm>

using namespace std;

class Solution {
public:
    int minSwaps(string s) {
        int balance = 0, maxImbalance = 0;
        for (char c : s) {
            balance += c == '[' ? 1 : -1;
            if (balance < 0) {
                maxImbalance = max(maxImbalance, -balance);
            }
        }
        return (maxImbalance + 1) / 2;
    }
};
